public class StandardRatePlan extends RatePlan {
    public StandardRatePlan() {
        super("STANDARD");
    }

    @Override
    public void validate(int roomCapacity, int guests, LocalDate checkIn, LocalDate checkOut, String companyCode) {
        if (guests < 1 || guests > roomCapacity) {
            throw new ValidationException("CAPACITY_EXCEEDED",
                "Número de hóspedes inválido para a capacidade do quarto");
        }
    }

    @Override
    public BigDecimal calculateSubtotal(BigDecimal nightlyRate, int nights, LocalDate checkIn, LocalDate checkOut) {
        BigDecimal total = BigDecimal.ZERO;
        LocalDate current = checkIn;
        while (current.isBefore(checkOut)) {
            BigDecimal rate = nightlyRate;
            if (isHighSeason(current)) {
                rate = rate.multiply(BigDecimal.valueOf(1.2));
            }
            rate = PricingUtils.roundHalfEven(rate);
            total = total.add(rate);
            current = current.plusDays(1);
        }
        return total;
    }

    @Override
    public BigDecimal calculateDiscount(BigDecimal subtotal) {
        return BigDecimal.ZERO;
    }

    @Override
    public BigDecimal calculateRefund(Reservation reservation) {
        if (reservation.getStatus() == Reservation.ReservationStatus.PENDING) {
            return BigDecimal.ZERO;
        }
        return reservation.getAmountPaid();
    }

    private boolean isHighSeason(LocalDate date) {
        int month = date.getMonthValue();
        int day = date.getDayOfMonth();

        if (month == 7) return true;
        if (month == 12 && day >= 15) return true;
        if (month == 1 || month == 2) return true;

        return false;
    }
}

